import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n = int(input())
        size = 3 ** n

        # Build the grid directly as a 2D list of characters.
        grid = [['#' for _ in range(size)] for _ in range(size)]

        # Recursively carve out the central holes.
        def carve(x, y, k):
            if k == 0:
                return
            step = 3 ** (k - 1)
            # Center block becomes '.'; recurse into the 8 surrounding blocks.
            cx, cy = x + step, y + step
            for i in range(cx, cx + step):
                for j in range(cy, cy + step):
                    grid[i][j] = '.'

            for dx in range(3):
                for dy in range(3):
                    if dx == 1 and dy == 1:
                        continue
                    carve(x + dx * step, y + dy * step, k - 1)

        carve(0, 0, n)

        for row in grid:
            print(''.join(row))

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

