import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, m = map(int, input().split())
        s = [input().strip() for _ in range(n)]

        best = 0
        # Enumerate all non-empty subsets of strings
        for mask in range(1, (1 << n)):
            c = [0] * 26
            for j in range(n):
                if (mask >> j) & 1:
                    sj = s[j]
                    for ch in sj:
                        idx = ord(ch) - ord('a')
                        if 0 <= idx < 26:
                            c[idx] += 1
            best = max(best, c.count(m))
        print(best)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

