def solve(text):
    def program():
        S = input()
        t = set([])
        a = [[]]
        for i in S:
            if i.isalpha() == True:
                if i in t:
                    print('No')
                    exit()
                else:
                    t.add(i)
                    a[-1].append(i)
            elif i == ')':
                for j in a[-1]:
                    print(t)
