patch:
def lcs_length(s, t):
    dp = {}
    max_len = 0

    for i in range(len(s)):
        for j in range(len(t)):
            if s[i] == t[j]:
                if i == 0 or j == 0:
                    dp[i, j] = 1
                else:
                    dp[i, j] = dp.get((i - 1, j - 1), 0) + 1
                if dp[i, j] > max_len:
                    max_len = dp[i, j]
            else:
                dp[i, j] = 0

    return max_len

