import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n = int(input())
        s = [str(input()) for _ in range(n)]

        # Count for each row i the number of 'o' in columns k where i != k.
        # (The previous version only counted for i > k, which misses half the matrix.)
        dic = {i: 0 for i in range(n)}
        for i in range(n):
            for k in range(n):
                if i != k and s[i][k] == 'o':
                    dic[i] += 1

        dic = sorted(dic.items(), key=lambda x: x[1], reverse=True)
        for i, _ in dic:
            print(i + 1, end=' ')

