import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        def calc(N, A):
            start = 0
            total = 0
            for i in A:
                total += i
                if -start > total:
                    start = -total
            return start + total

        def main():
            data = sys.stdin.read().strip().split()
            if not data:
                return
            it = iter(data)
            N = int(next(it))
            A = []
            for _ in range(N):
                try:
                    A.append(int(next(it)))
                except StopIteration:
                    break
            print(calc(N, A))

        main()

