import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N = int(input())
        P = list(map(int, input().split()))
        # pos[x] = position (0-indexed) of value x in the permutation
        pos = [0] * (N + 1)
        for i, v in enumerate(P):
            pos[v] = i

        # flg[a][b] = True if value a should come before value b
        flg = [[False] * (N + 1) for _ in range(N + 1)]
        for a in range(1, N + 1):
            for b in range(1, N + 1):
                if a == b:
                    continue
                flg[a][b] = pos[a] < pos[b]

        Q = int(input())
        for _ in range(Q):
            A, B = map(int, input().split())
            if flg[A][B]:
                print(A)
            else:
                print(B)

