from bisect import bisect_left


def solve(text):
    def program():
        input = lambda: sys.stdin.readline().rstrip('\r\n')
        II = lambda: int(input())
        LII = lambda: list(map(int, input().split()))

        def abc354_f():
            for _ in range(II()):
                n = II()
                a = LII()

                # pre[i] = length of LIS (strictly increasing) ending at i
                pre = [0] * n
                g = []
                for i, x in enumerate(a):
                    idx = bisect_left(g, x)
                    if idx < len(g):
                        g[idx] = x
                    else:
                        g.append(x)
                    pre[i] = idx + 1

                # suf[i] = length of LIS (strictly increasing) starting at i
                # Compute via LIS on reversed with negated values.
                suf = [0] * n
                g = []
                for i in range(n - 1, -1, -1):
                    v = -a[i]
                    idx = bisect_left(g, v)
                    if idx < len(g):
                        g[idx] = v
                    else:
                        g.append(v)
                    suf[i] = idx + 1

                max_len = max(pre) if n > 0 else 0

                ans = []
                for i in range(n):
                    if pre[i] + suf[i] - 1 == max_len:
                        ans.append(i + 1)

                print(len(ans))
                if ans:
                    print(*ans)

        abc354_f()

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

