def solve(text):
    def program():
        N = int(input())
        skill = []
        for _ in range(N):
            skill.append(list(map(int, input().split())))

        # Determine whether dependency indices are 0-based or 1-based.
        # We infer this from the observed dependency values in the input.
        max_dep = -1
        min_dep = 10**18
        for i in range(N):
            deps = skill[i][2:]
            if deps:
                max_dep = max(max_dep, max(deps))
                min_dep = min(min_dep, min(deps))

        # If dependencies include 0, they are 0-based; otherwise assume 1-based.
        # (This avoids blindly subtracting and breaking the 0-based case.)
        deps_are_zero_based = (min_dep == 0)

        need = [False] * N
