import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N, M = map(int, input().split())
        MOD = 998244353
        ret = 0
        for i in range(60):
            # Only process bit i if it is set in M
            if M & (1 << i):
                tmp = N // ((1 << i) * 2)
                ret = (ret + tmp * (1 << i)) % MOD
                tmp = N % ((1 << i) * 2)
                if tmp >= (1 << i):
                    ret = (ret + tmp - (1 << i) + 1) % MOD
        print(ret)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
