import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, m = map(int, input().split())
        s = [input() for i in range(n)]
        a = 0
        for i in range(1, (1 << n) - 1):
            c = [0] * 26
            for j in range(n):
