import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, m = map(int, input().split())
        s = [input().strip() for _ in range(n)]

        # Precompute bitmasks of characters present in each string
        masks = []
        for st in s:
            mask = 0
            for ch in set(st):
                mask |= 1 << (ord(ch) - ord('a'))
            masks.append(mask)

        best = 0
        # Iterate over all non-empty subsets of strings (including full subset)
        for subset in range(1, 1 << n):
            # Count for each character how many strings in subset contain it
            c = [0] * 26
            for j in range(n):
                if (subset >> j) & 1:
                    mj = masks[j]
                    for k in range(26):
                        if (mj >> k) & 1:
                            c[k] += 1
            best = max(best, c.count(m))

        print(best)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

