import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        from collections import Counter
        from functools import reduce

        N = int(input())

        def prime_factorize(n):
            a = []
            while n % 2 == 0:
                a.append(2)
                n //= 2
            f = 3
            while f * f <= n:
                if n % f == 0:
                    a.append(f)
                    n //= f
                else:
                    f += 2
            if n != 1:
                a.append(n)
            return a

        def num_divisors(n):
            if n == 1:
                return 1
            return reduce(
                lambda x, y: x * (y + 1),
                Counter(prime_factorize(n)).values(),
                1
            )

        cnt = 0
        # Enumerate all ordered splits (AB, CD) with AB + CD = N.
        # This avoids relying on the *2 trick and fixes missing contributions.
        for AB in range(1, N):
            CD = N - AB
            cntAB = num_divisors(AB)
            cntCD = num_divisors(CD)
            cnt += cntAB * cntCD

        print(cnt)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

