def solve(text):
    def program():
        N = int(input())
        C, A = ([], [])
        for _ in range(N):
            C.append(int(input()))
            A.append(list(map(int, input().split())))
        X = int(input())

        # Find indices (1-based) of arrays containing X with minimal length
        min_len = None
        R = []
        for i in range(N):
            if X in A[i]:
                cur_len = len(A[i])
                if min_len is None or cur_len < min_len:
                    min_len = cur_len
                    R = [i + 1]
                elif cur_len == min_len:
                    R.append(i + 1)

        print(len(R))
        for r in R:
            print(r, end=' ')

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
