import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n = int(input())
        # Use correct bounds: coordinates are in [0, 100], so we need indices 0..100 inclusive.
        f = [[0] * 101 for _ in range(101)]
        for _ in range(n):
            a, b, c, d = map(int, input().split())
            # Mark all unit squares in the half-open ranges [a,b) and [c,d)
            for x in range(a, b):
                for y in range(c, d):
                    f[x][y] = 1

        # Sum over the full grid, not just the first 10 rows.
        ans = 0
        for i in range(101):
            ans += sum(f[i])
        print(ans)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

