import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        n, t, l = map(int, input().split())
        INF = t + 1

        # mat[u][v] = minimal "edge cost" for a single step, or INF if absent
        mat = [[INF] * n for _ in range(n)]
        for i in range(1, t + 1):
            u, v = map(int, input().split())
            mat[u - 1][v - 1] = i

        def mul(A, B):
            # Min-max multiplication:
            # (A ⊗ B)[i][k] = min_j max(A[i][j], B[j][k])
            res = [[INF] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    aij = A[i][j]
                    if aij == INF:
                        continue
                    for k in range(n):
                        res[i][k] = min(res[i][k], max(aij, B[j][k]))
            return res

        def mat_pow(M, k):
            # Identity for min-max multiplication:
            # I[i][i] = 0 (so max(x,0)=x), I[i][j!=i]=INF (so min over paths ignores them)
            res = [[INF] * n for _ in range(n)]
            for i in range(n):
                res[i][i] = 0
            while k:
                if k & 1:
                    res = mul(res, M)
                M = mul(M, M)
                k >>= 1
            return res

        res = mat_pow(mat, l)[0]
        for i in range(n):
            if res[i] > t:
                res[i] = -1
        print(*res)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

