import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        N, M = map(int, input().split())
        MOD = 998244353
        ret = 0
        for i in range(60):
            if M and 2 ** i:
                tmp = N // (2 ** i * 2)
                ret = ret + tmp * 2 ** i
                tmp = N % (2 ** i * 2)
                if tmp >= 2 ** i:
                    ret = ret + tmp - 2 ** i + 1
                ret = ret % MOD
        print(ret)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

