import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        from collections import Counter
        from functools import reduce

        N = int(input())

        def prime_factorize(n):
            a = []
            while n % 2 == 0:
                a.append(2)
                n //= 2
            f = 3
            while f * f <= n:
                if n % f == 0:
                    a.append(f)
                    n //= f
                else:
                    f += 2
            if n != 1:
                a.append(n)
            return a

        def divisor_count(n):
            if n == 1:
                return 1
            return reduce(
                lambda x, y: x * (y + 1),
                Counter(prime_factorize(n)).values(),
                1
            )

        cnt = 0
        # Iterate over all ordered splits (A,B) and (C,D) with AB + CD = N
        # The previous code only iterated AB <= N/2 and tried to compensate with
        # a symmetry factor, which was inconsistent. We count directly over all AB.
        for AB in range(1, N):
            CD = N - AB
            cntAB = divisor_count(AB)
            cntCD = divisor_count(CD)
            cnt += cntAB * cntCD

        print(cnt)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

