import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        def factorization(n):
            now_num = n
            prime_cnt_list = []
            for i in range(2, n + 1):
                if i * i > now_num:
                    break
                if now_num % i:
                    continue
                cnt = 0
                while not now_num % i:
                    now_num //= i
                    cnt += 1
                prime_cnt_list.append((i, cnt))
            if now_num != 1:
                prime_cnt_list.append((now_num, 1))
            return prime_cnt_list
        N = int(input())
        ans = 0
        for i in range(1, N + 1):
            fc = factorization(i)
            odd = 1
            for p, cnt in fc:
                if cnt % 2 == 1:
                    odd *= p
            for j in range(1, N + 1):
                if odd * j * j > N:
                    break
                ans += 1
        print(ans)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

patch:
import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        def factorization(n):
            now_num = n
            prime_cnt_list = []
            for i in range(2, n + 1):
                if i * i > now_num:
                    break
                if now_num % i != 0:
                    continue
                cnt = 0
                while now_num % i == 0:
                    now_num //= i
                    cnt += 1
                prime_cnt_list.append((i, cnt))
            if now_num != 1:
                prime_cnt_list.append((now_num, 1))
            return prime_cnt_list

        N = int(input())
        ans = 0
        for i in range(1, N + 1):
            fc = factorization(i)
            odd = 1
            for p, cnt in fc:
                if cnt % 2 == 1:
                    odd *= p

            # Count j such that odd * j^2 <= N
            # i.e., j <= floor(sqrt(N / odd))
            if odd > 0:
                max_j = int((N // odd) ** 0.5)
                ans += max_j
        print(ans)

    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

original:
import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        A, B = map(int, input().split())
        print(A ^ B)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

